// Registre des capteurs connus : sensorId -> senior, type de capteur, canal d'arrivée.
// Un message d'un capteur absent de cette liste est rejeté (UNKNOWN_SENSOR).
global.set('sensorRegistry', {
    'pir-cuisine':  { seniorId: 'senior-001', channel: 'MQTT', kind: 'PIR', room: 'cuisine' },
    'pir-salon':    { seniorId: 'senior-001', channel: 'MQTT', kind: 'PIR', room: 'salon' },
    'pir-chambre':  { seniorId: 'senior-001', channel: 'MQTT', kind: 'PIR', room: 'chambre' },
    'plate-lit':    { seniorId: 'senior-001', channel: 'MQTT', kind: 'PRESSURE_PLATE', room: 'chambre', location: 'lit' },
    'plate-fauteuil': { seniorId: 'senior-001', channel: 'MQTT', kind: 'PRESSURE_PLATE', room: 'salon', location: 'fauteuil' },
    'watch-001':    { seniorId: 'senior-001', channel: 'HTTP', kind: 'WATCH' }
});

