// Répond à l'appelant HTTP (appli de la montre). Ignore les messages venus de MQTT.
if (!msg.res) { return null; }

const rejected = msg.topic === 'ingestion/rejected';
msg.statusCode = rejected ? 422 : 202;
msg.payload = rejected
    ? { accepted: false, reason: msg.payload.reason, details: msg.payload.details }
    : { accepted: true, eventId: msg.payload.eventId };
return msg;
